#!/usr/bin/env node
// Generates the website's and the app's colour files from design-tokens/tokens.json.
//   node design-tokens/build.mjs           write the files
//   node design-tokens/build.mjs --check   fail if any generated file is out of date
import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const { color } = JSON.parse(readFileSync(join(root, 'design-tokens/tokens.json'), 'utf8'));
const names = Object.keys(color);
const HEADER = 'Generated by design-tokens/build.mjs from design-tokens/tokens.json. Do not edit by hand.';

const hex = (value) => {
  if (!/^#[0-9A-Fa-f]{6}$/.test(value)) throw new Error(`Not a #RRGGBB colour: ${value}`);
  return value.toUpperCase();
};
const rgb = (value) => [1, 3, 5].map((i) => parseInt(hex(value).slice(i, i + 2), 16)).join(' ');
const camel = (name) => name.replace(/-([a-z0-9])/g, (_, c) => c.toUpperCase());
const tsMap = (mode) => names.map((n) => `  ${camel(n)}: '${hex(color[n][mode])}',`).join('\n');

const files = {
  // App: NativeWind reads the variables; tailwind.config.js maps class names onto them.
  'jobblo-app/app/global.css': [
    '@tailwind base;',
    '@tailwind components;',
    '@tailwind utilities;',
    '',
    `/* ${HEADER} */`,
    '@layer base {',
    '  :root {',
    ...names.map((n) => `    --${n}: ${rgb(color[n].light)};`),
    '  }',
    '  .dark:root {',
    ...names.map((n) => `    --${n}: ${rgb(color[n].dark)};`),
    '  }',
    '}',
    '',
  ].join('\n'),

  'jobblo-app/src/theme/tailwindColors.js': [
    `// ${HEADER}`,
    'module.exports = {',
    ...names.map((n) => `  '${n}': 'rgb(var(--${n}) / <alpha-value>)',`),
    '};',
    '',
  ].join('\n'),

  // App + website: plain hex for props and JS (icons, inline styles, brand.ts).
  'jobblo-app/src/theme/tokens.ts': [
    `// ${HEADER}`,
    `export const LIGHT = {\n${tsMap('light')}\n};`,
    '',
    `export const DARK: typeof LIGHT = {\n${tsMap('dark')}\n};`,
    '',
  ].join('\n'),

  'frontend/src/theme/tokens.ts': [
    `// ${HEADER}`,
    `export const LIGHT = {\n${tsMap('light')}\n} as const;`,
    '',
    `export const DARK = {\n${tsMap('dark')}\n} as const;`,
    '',
  ].join('\n'),

  // Website: Tailwind v4 theme colours, as `bg-jb-page`, `text-jb-ink`, `border-jb-line`, ...
  'frontend/src/styles/tokens.css': [
    `/* ${HEADER} */`,
    '@theme {',
    ...names.map((n) => `  --color-jb-${n}: ${hex(color[n].light)};`),
    '}',
    '',
    '.dark {',
    ...names.map((n) => `  --color-jb-${n}: ${hex(color[n].dark)};`),
    '}',
    '',
  ].join('\n'),
};

const check = process.argv.includes('--check');
const stale = [];
for (const [rel, content] of Object.entries(files)) {
  const path = join(root, rel);
  const current = existsSync(path) ? readFileSync(path, 'utf8').replace(/\r\n/g, '\n') : null;
  if (current === content) continue;
  if (check) stale.push(rel);
  else writeFileSync(path, content);
}
if (stale.length) {
  console.error(`Out of date (run node design-tokens/build.mjs):\n  ${stale.join('\n  ')}`);
  process.exit(1);
}
console.log(check ? 'design tokens: all generated files up to date' : `design tokens: wrote ${Object.keys(files).length} files`);
